from collections import deque
def bfs(g, starts, ends):
    H,W=len(g),len(g[0]); dist={tuple(s):0 for s in starts}; dq=deque(starts)
    endset=set(tuple(e) for e in ends)
    while dq:
        u=dq.popleft()
        if u in endset and tuple(u)!=tuple(next(iter(starts))): break
        i,j=u
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            v=(i+di,j+dj)
            if 0<=v[0]<H and 0<=v[1]<W and tuple(v) not in dist and g[v[0]][v[1]]==0:
                dist[tuple(v)]=dist[u]+1; dq.append(v)
    near=min(dist[e] for e in endset)
    return near
